package cz.mh.rallye.rallye_backend.participation;

import java.time.*;
import java.util.*;
import java.util.concurrent.atomic.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.SimpleTransactionStatus;
import cz.mh.rallye.rallye_backend.identity.application.*;
import cz.mh.rallye.rallye_backend.identity.persistence.*;
import cz.mh.rallye.rallye_backend.crews.persistence.CrewStore;
import cz.mh.rallye.rallye_backend.races.persistence.EventStore;
import cz.mh.rallye.rallye_backend.races.application.LifecycleService;
import cz.mh.rallye.rallye_backend.participation.application.*;
import cz.mh.rallye.rallye_backend.participation.persistence.*;
import cz.mh.rallye.rallye_backend.participation.persistence.CrewStartStore.*;
import cz.mh.rallye.rallye_backend.audit.application.AuditService;
import cz.mh.rallye.rallye_backend.shared.persistence.CommandStore;

class StartCodeServiceTest {
 final CrewStartStore store=mock(CrewStartStore.class);final RegistrationStore registrations=mock(RegistrationStore.class);final CrewStore crews=mock(CrewStore.class);final AccountStore accounts=mock(AccountStore.class);final AdminStore roles=mock(AdminStore.class);final CommandStore ledger=mock(CommandStore.class);final AuditService audit=mock(AuditService.class);final CrewStartSecrets secrets=mock(CrewStartSecrets.class);final EventStore events=mock(EventStore.class);final LifecycleService lifecycle=mock(LifecycleService.class);final PlatformTransactionManager manager=mock(PlatformTransactionManager.class);
 final UUID event=UUID.randomUUID(),reg=UUID.randomUUID(),crew=UUID.randomUUID(),run=UUID.randomUUID();final Instant now=Instant.parse("2026-10-31T12:00:00Z");final AuthService.Principal actor=new AuthService.Principal(UUID.randomUUID(),UUID.randomUUID(),false);
 final Map<UUID,Code> codes=new LinkedHashMap<>();final Map<UUID,Command> commands=new HashMap<>();final AtomicReference<Registration> registration=new AtomicReference<>(new Registration(reg,event,null,0,0,null));StartCodeService service;
 EventStore.Event event(String status,Instant end){return new EventStore.Event(event,UUID.randomUUID(),0,"Event",null,0,status,null,end,0,now,now);}
 @BeforeEach void setup(){service=new StartCodeService(store,registrations,crews,accounts,roles,ledger,audit,secrets,new SecretTokens(),events,lifecycle,Clock.fixed(now,ZoneOffset.UTC),manager);when(manager.getTransaction(any())).thenAnswer(i->new SimpleTransactionStatus());when(roles.activeVerified(actor.accountId())).thenReturn(true);when(roles.administrator(actor.accountId())).thenReturn(true);when(accounts.isActiveSession(any(),any(),any())).thenReturn(true);when(registrations.crew(event,reg)).thenReturn(crew);when(events.lock(event)).thenReturn(event("PLANNED",now.plusSeconds(3600)));when(lifecycle.reconcile(any(),any(),eq(true),any())).thenAnswer(i->i.getArgument(0));when(store.registration(reg,true)).thenAnswer(i->registration.get());when(store.touchRegistration(eq(reg),anyLong(),any())).thenAnswer(i->{var r=registration.get();if(r.version()!=(Long)i.getArgument(1))return false;registration.set(new Registration(reg,event,r.currentRunId(),r.deviceGeneration(),r.version()+1,r.startedAt()));return true;});when(store.nextCodeGeneration(reg)).thenAnswer(i->codes.values().stream().mapToLong(Code::generation).max().orElse(0)+1);AtomicInteger generated=new AtomicInteger();when(secrets.newCode()).thenAnswer(i->String.format("C%05d",generated.incrementAndGet()));when(store.codeValueExists(eq(reg),any())).thenAnswer(i->codes.values().stream().anyMatch(c->c.value().equals(i.getArgument(1))));doAnswer(i->{Code c=i.getArgument(0);codes.put(c.id(),c);return null;}).when(store).insertCode(any());when(store.code(eq(reg),any(),eq(false))).thenAnswer(i->codes.get(i.getArgument(1)));when(store.command(eq(actor.accountId()),any())).thenAnswer(i->commands.get(i.getArgument(1)));doAnswer(i->{Command c=i.getArgument(0);commands.put(c.key(),c);return null;}).when(store).insertCommand(any());}
 String failure(Runnable work){return assertThrows(AuthFailure.class,work::run).code();}
 @Test void originalsAreOnePairAndOneVersionWithSafeReceipts(){UUID key=UUID.randomUUID();var result=service.originals(actor,event,reg,key,0);assertEquals(2,result.codes().size());assertNotEquals(result.codes().get(0).code(),result.codes().get(1).code());assertEquals(List.of(1L,2L),result.codes().stream().map(StartCodeService.CodeResult::generation).toList());assertEquals(1,result.registrationVersion());assertEquals(result,service.originals(actor,event,reg,key,0));verify(audit,times(1)).startCodes(any(),eq(AuditService.Event.START_CODES_ISSUED),eq(reg),eq(event),any(),anyList(),eq(1L),eq(0L));Command evidence=commands.get(key);assertNotNull(evidence.secondCodeId());for(Code c:codes.values())assertFalse(evidence.resultJson().contains(c.value()));verify(ledger).save(eq(actor.accountId()),eq(key),eq(reg),eq("RACE_ORIGINAL_ISSUE"),argThat(s->!s.contains(result.codes().getFirst().code())),argThat(s->!s.contains(result.codes().getFirst().code())),eq(now));assertEquals("ORIGINAL_CODES_ALREADY_ISSUED",failure(()->service.originals(actor,event,reg,UUID.randomUUID(),1)));}
 @Test void replayHidesUsedCodeButKeepsOtherCodeAndDoesNotChangeVersion(){UUID key=UUID.randomUUID();var first=service.originals(actor,event,reg,key,0);Code c=codes.get(first.codes().getFirst().id());codes.put(c.id(),new Code(c.id(),reg,c.kind(),c.generation(),"USED",c.value(),c.issuedAt(),c.issuedBy(),now,UUID.randomUUID(),0,null,1));var replay=service.originals(actor,event,reg,key,0);assertNull(replay.codes().getFirst().code());assertEquals("USED",replay.codes().getFirst().state());assertEquals(first.codes().get(1),replay.codes().get(1));assertEquals(1,registration.get().version());assertEquals("IDEMPOTENCY_CONFLICT",failure(()->service.originals(actor,event,reg,key,1)));}
 void started(){registration.set(new Registration(reg,event,run,1,4,now));when(events.lock(event)).thenReturn(event("RUNNING",now.plusSeconds(3600)));when(store.run(reg,run,true)).thenReturn(new Run(run,reg,event,1,"RUNNING",1,now,null,null,0));Code original=new Code(UUID.randomUUID(),reg,"ORIGINAL",2,"AVAILABLE","ORIG02",now,actor.accountId(),null,null,0,null,0);codes.put(original.id(),original);}
 @Test void replacementPointsAreStoredOnlyAndOldCodesRemain(){started();for(long points:List.of(0L,7L,-5L,Long.MIN_VALUE,Long.MAX_VALUE)){long version=registration.get().version();var result=service.replacement(actor,event,reg,UUID.randomUUID(),version,points," reason ");assertEquals(Long.toString(points),result.code().pointsAdjustment());assertEquals(version+1,result.registrationVersion());assertEquals("AVAILABLE",result.code().state());}assertEquals(6,codes.size());assertTrue(codes.values().stream().allMatch(c->c.state().equals("AVAILABLE")));verify(store,never()).consumeCode(any(),any(),anyLong(),any(),any());verify(store,never()).insertDevice(any());verify(store,never()).revokeDevice(any(),any(),anyLong(),any(),any(),any());verify(store,never()).insertAdjustment(any());verify(store,never()).touchRun(any(),any(),anyLong());}
 @Test void replacementReplayCanonicalizesReasonAndDetectsChangedPoints(){started();UUID key=UUID.randomUUID();var result=service.replacement(actor,event,reg,key,4,0," reason ");assertEquals(result,service.replacement(actor,event,reg,key,4,0,"reason"));assertEquals("IDEMPOTENCY_CONFLICT",failure(()->service.replacement(actor,event,reg,key,4,1,"reason")));verify(audit,times(1)).startCodes(any(),any(),any(),any(),any(),anyList(),anyLong(),anyLong());}
 @Test void authorizationIsRecheckedBeforeReplayAndBeforeReading(){UUID key=UUID.randomUUID();service.originals(actor,event,reg,key,0);when(roles.administrator(actor.accountId())).thenReturn(false);assertEquals("ADMIN_REQUIRED",failure(()->service.originals(actor,event,reg,key,0)));assertEquals("ADMIN_REQUIRED",failure(()->service.list(actor,event,reg,0,50)));assertEquals("INVALID_CREDENTIALS",failure(()->service.originals(null,event,reg,key,0)));}
 @Test void stateErrorsRespectVersionThenEndAndDoNotIssue(){when(events.lock(event)).thenReturn(event("ENDED",now));assertEquals("REGISTRATION_VERSION_CONFLICT",failure(()->service.originals(actor,event,reg,UUID.randomUUID(),1)));assertEquals("RACE_ENDED",failure(()->service.originals(actor,event,reg,UUID.randomUUID(),0)));when(events.lock(event)).thenReturn(event("PLANNED",now.plusSeconds(3600)));assertEquals("RACE_NOT_STARTED",failure(()->service.replacement(actor,event,reg,UUID.randomUUID(),0,0,null)));when(events.lock(event)).thenReturn(event("RUNNING",now.plusSeconds(3600)));assertEquals("PARTICIPATION_NOT_STARTED",failure(()->service.replacement(actor,event,reg,UUID.randomUUID(),0,0,null)));started();when(store.run(reg,run,true)).thenReturn(new Run(run,reg,event,1,"COMPLETED",1,now,now,now,0));assertEquals("RUN_ALREADY_COMPLETED",failure(()->service.replacement(actor,event,reg,UUID.randomUUID(),4,0,null)));verifyNoInteractions(audit);assertTrue(codes.values().stream().noneMatch(c->c.kind().equals("REPLACEMENT")));}
 @Test void missingParentsDoNotIssue(){when(events.lock(event)).thenReturn(null);assertEquals("RACE_EVENT_NOT_FOUND",failure(()->service.originals(actor,event,reg,UUID.randomUUID(),0)));when(events.lock(event)).thenReturn(event("PLANNED",null));when(registrations.crew(event,reg)).thenReturn(null);assertEquals("REGISTRATION_NOT_FOUND",failure(()->service.originals(actor,event,reg,UUID.randomUUID(),0)));assertTrue(codes.isEmpty());}
 @Test void auditFailureRollsBackTransactionAndIs503(){doThrow(new IllegalStateException("Injected")).when(audit).startCodes(any(),any(),any(),any(),any(),anyList(),anyLong(),anyLong());assertEquals("RACE_STATE_UNAVAILABLE",failure(()->service.originals(actor,event,reg,UUID.randomUUID(),0)));verify(manager).rollback(any());verify(manager,never()).commit(any());}
 @Test void collisionBudgetFailsWithoutCommittingPartialPair(){when(secrets.newCode()).thenReturn("ABC123");assertEquals("RACE_STATE_UNAVAILABLE",failure(()->service.originals(actor,event,reg,UUID.randomUUID(),0)));verify(secrets,times(21)).newCode();verify(manager).rollback(any());verifyNoInteractions(audit);}
 @Test void namespaceConflictAndInvalidReasonAreRejected(){when(ledger.replay(any(),any(),any(),any(),any())).thenThrow(new AuthFailure(409,"IDEMPOTENCY_CONFLICT"));assertEquals("IDEMPOTENCY_CONFLICT",failure(()->service.originals(actor,event,reg,UUID.randomUUID(),0)));assertEquals("INVALID_REQUEST",failure(()->service.replacement(actor,event,reg,UUID.randomUUID(),0,0,"x".repeat(2001))));}
 @Test void listAndDetailHideUsedValuesAndParentScopeIsChecked(){var row=new RegistrationStore.Row(reg,event,crew,"Crew","REGISTERED",0,now,now,"One",0,null,null,actor.accountId());when(registrations.event(event,false)).thenReturn(new RegistrationStore.Event(event,"Event",null,"PLANNED",null,null,null,0,null,null,"AUTO"));when(registrations.row(event,reg,false)).thenReturn(row);var pair=service.originals(actor,event,reg,UUID.randomUUID(),0);when(store.codes(reg,0,1)).thenReturn(new ArrayList<>(codes.values()));assertTrue(service.list(actor,event,reg,0,1).hasMore());assertEquals(1,service.list(actor,event,reg,0,1).items().size());Code c=codes.values().iterator().next();assertEquals(c.value(),service.detail(actor,event,reg,c.id()).code());codes.put(c.id(),new Code(c.id(),reg,c.kind(),c.generation(),"USED",c.value(),now,actor.accountId(),now,UUID.randomUUID(),0,null,1));assertNull(service.detail(actor,event,reg,c.id()).code());assertEquals("START_CODE_NOT_FOUND",failure(()->service.detail(actor,event,reg,UUID.randomUUID())));assertEquals("INVALID_REQUEST",failure(()->service.list(actor,event,reg,0,101)));assertFalse(pair.toString().contains(c.value()));}
}
